    src=src.replace("signatureData=null;confirmed=false;$('confirmSignatureBtn').disabled=true;$('createImageBtn').disabled=true","signatureData=null;confirmed=false;saveLangSignatureState();$('confirmSignatureBtn').disabled=true;$('createImageBtn').disabled=true");
